int ioctl(int fd, int op, ... /* arg */);

// --- Terminal Control (termios) ---
struct termios settings;
// Get current attributes
ioctl(fd, TCGETS, &settings); 
// Set attributes immediately
ioctl(fd, TCSANOW, &settings); 
// Set attributes after output drains
ioctl(fd, TCSADRAIN, &settings);

// --- Window Size Control ---
struct winsize ws;
// Get current window dimensions
ioctl(fd, TIOCGWINSZ, &ws);
// Set window dimensions
ioctl(fd, TIOCSWINSZ, &ws);

// Example: Send signal to background process group
ioctl(fd, TIOCSIG, SIGINT);
